static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int kthHighest(int* bids, int bidsSize, int k) {
    int* a = malloc(bidsSize * sizeof(int));
    memcpy(a, bids, bidsSize * sizeof(int));
    qsort(a, bidsSize, sizeof(int), cmp_int);
    int answer = a[bidsSize - k];
    free(a);
    return answer;
}

