class Solution {
    public int kthHighest(int[] bids, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int b : bids) {
            heap.add(b);
            if (heap.size() > k) heap.poll();
        }
        return heap.peek();
    }
}

