static void push(int* h, int* n, int x) {
    int i = (*n)++;
    while (i > 0 && h[(i - 1) / 2] > x) { h[i] = h[(i - 1) / 2]; i = (i - 1) / 2; }
    h[i] = x;
}

static void pop(int* h, int* n) {
    int x = h[--(*n)], i = 0;
    for (int c = 1; c < *n; i = c, c = 2 * c + 1) {
        if (c + 1 < *n && h[c + 1] < h[c]) c++;
        if (h[c] >= x) break;
        h[i] = h[c];
    }
    if (*n > 0) h[i] = x;
}

int kthHighest(int* bids, int bidsSize, int k) {
    int* heap = malloc((k + 1) * sizeof(int));
    int n = 0;
    for (int i = 0; i < bidsSize; i++) {
        push(heap, &n, bids[i]);
        if (n > k) pop(heap, &n);
    }
    int answer = heap[0];
    free(heap);
    return answer;
}

