                if (a[i] < p) swap(a[lt++], a[i++]);
                else if (a[i] > p) swap(a[i], a[gt--]);
                else i++;
            }
            if (target < lt) hi = lt - 1;
            else if (target > gt) lo = gt + 1;
            else return p;
        }
